begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values('bbbbbbbb-1111-4111-8111-bbbbbbbbbbbb','interface-a@example.invalid'),('cccccccc-1111-4111-8111-cccccccccccc','interface-b@example.invalid');
insert into tutor_conversations(id,user_id,context,context_hash) values('11111111-2222-4222-8222-111111111111','bbbbbbbb-1111-4111-8111-bbbbbbbbbbbb','{}',repeat('a',64)),('22222222-2222-4222-8222-222222222222','cccccccc-1111-4111-8111-cccccccccccc','{}',repeat('b',64));
insert into tutor_messages(conversation_id,role,content) values('11111111-2222-4222-8222-111111111111','user','{"text":"test"}'),('11111111-2222-4222-8222-111111111111','assistant','{"text":"answer"}'),('22222222-2222-4222-8222-222222222222','assistant','{"text":"other answer"}');
create function public.interface_report(rid uuid,cid uuid,role text default 'assistant',note text default 'needs review') returns jsonb language sql as $$
 select jsonb_build_object('id',rid,'conversationId',cid,'messageId',(select id from tutor_messages where conversation_id=cid and tutor_messages.role=interface_report.role limit 1),'category','incorrect','message',note)
$$;
select ok((select relrowsecurity from pg_class where oid='public.tutor_reports'::regclass),'Tutor report RLS');
select ok(not has_function_privilege('authenticated','submit_tutor_report(uuid,jsonb)','execute'),'Client cannot call private submit RPC');
set local role service_role;
select is(submit_tutor_report('bbbbbbbb-1111-4111-8111-bbbbbbbbbbbb',interface_report('aaaaaaaa-2222-4222-8222-aaaaaaaaaaaa','11111111-2222-4222-8222-111111111111'))->>'accepted','aaaaaaaa-2222-4222-8222-aaaaaaaaaaaa','Own stored assistant answer reportable');
select is(submit_tutor_report('bbbbbbbb-1111-4111-8111-bbbbbbbbbbbb',interface_report('aaaaaaaa-2222-4222-8222-aaaaaaaaaaaa','11111111-2222-4222-8222-111111111111'))->>'accepted','aaaaaaaa-2222-4222-8222-aaaaaaaaaaaa','Identical report retry idempotent');
select is((select count(*)::integer from tutor_reports),1,'Retry creates only one report');
select is(submit_tutor_report('bbbbbbbb-1111-4111-8111-bbbbbbbbbbbb',interface_report('aaaaaaaa-2222-4222-8222-aaaaaaaaaaaa','11111111-2222-4222-8222-111111111111','assistant','changed'))->>'error','conflict','Changed ID cannot rewrite report');
select is(submit_tutor_report('bbbbbbbb-1111-4111-8111-bbbbbbbbbbbb',interface_report('dddddddd-2222-4222-8222-dddddddddddd','22222222-2222-4222-8222-222222222222'))->>'error','missing','Other account answer cannot be reported');
select is(submit_tutor_report('bbbbbbbb-1111-4111-8111-bbbbbbbbbbbb',interface_report('dddddddd-2222-4222-8222-dddddddddddd','11111111-2222-4222-8222-111111111111','user'))->>'error','missing','Own question is not an AI answer');
select throws_ok($$select submit_tutor_report('bbbbbbbb-1111-4111-8111-bbbbbbbbbbbb',interface_report('dddddddd-2222-4222-8222-dddddddddddd','11111111-2222-4222-8222-111111111111','assistant',repeat('x',2001)))$$,'P0001','Invalid tutor report','Report text bound');
select throws_ok($$select submit_tutor_report(null,interface_report('dddddddd-2222-4222-8222-dddddddddddd','11111111-2222-4222-8222-111111111111'))$$,'P0001','Invalid tutor report','Actor required');
select is(submit_tutor_report('cccccccc-1111-4111-8111-cccccccccccc',interface_report('dddddddd-2222-4222-8222-dddddddddddd','22222222-2222-4222-8222-222222222222'))->>'accepted','dddddddd-2222-4222-8222-dddddddddddd','Second actor owns their report');
set local role anon;
select throws_ok('select * from tutor_reports','42501',null,'Guests cannot read reports');
set local role authenticated;
set local request.jwt.claims='{"sub":"bbbbbbbb-1111-4111-8111-bbbbbbbbbbbb","role":"authenticated"}';
select is((select count(*)::integer from tutor_reports),1,'Only own reports visible');
select throws_ok($$insert into tutor_reports(id,user_id,conversation_id,message_id,category,message) select id,user_id,conversation_id,message_id,category,'fake' from tutor_reports$$,'42501',null,'No direct client writes');
select throws_ok($$delete from tutor_reports$$,'42501',null,'No direct client deletes');
select throws_ok($$select submit_tutor_report('bbbbbbbb-1111-4111-8111-bbbbbbbbbbbb','{}')$$,'42501',null,'Account cannot forge private actor');
set local role service_role;
select ok(delete_tutor_conversation('bbbbbbbb-1111-4111-8111-bbbbbbbbbbbb','11111111-2222-4222-8222-111111111111'),'Conversation deletion');
select is((select count(*)::integer from tutor_reports where user_id='bbbbbbbb-1111-4111-8111-bbbbbbbbbbbb'),0,'Conversation deletion removes associated reports');
select is((select count(*)::integer from tutor_reports),1,'Other actor report remains');
reset role;
delete from auth.users where id='cccccccc-1111-4111-8111-cccccccccccc';
select is((select count(*)::integer from tutor_reports),0,'Account deletion removes reports');
select * from finish();
rollback;
